import { CUSTOM_SOURCE_GROUPS, METRICS, sourceInstitutionAllowed } from '../config.js';
import { findCountry } from '../merge.js';
import { normalizePeriod, parseNumber, parseCSV, sleep, fetchText, fetchJSON } from '../utils.js';
import { officialUrlMatches, verified } from '../verification.js';

const BROWSER_DELAY_MS = 12000;
let lastBrowserCall = 0;

function num(v){
  if(v===null||v===undefined) return null;
  return parseNumber(String(v).replace(/\s/g,'').replace(/,(?=\d{1,3}(?:\D|$))/g,'.'));
}

function decodeEntities(text){
  return String(text).replace(/&quot;/gi,'"').replace(/&#39;|&apos;/gi,"'")
    .replace(/&#x([0-9a-f]+);/gi,(_,v)=>String.fromCodePoint(parseInt(v,16)))
    .replace(/&#([0-9]+);/g,(_,v)=>String.fromCodePoint(Number(v)))
    .replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&amp;/gi,'&');
}

function statsNZPage(html){
  const match=String(html).match(/id=["']pageViewData["'][^>]*data-value="([^"]*)"/i);
  if(!match) return null;
  try { return JSON.parse(decodeEntities(match[1])); } catch { return null; }
}

function htmlToText(html){
  return decodeEntities(html)
    .replace(/<!--[\s\S]*?-->/g,' ')
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,' ')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,' ')
    .replace(/<[^>]+>/g,' ')
    .replace(/&nbsp;|&#160;/gi,' ')
    .replace(/&amp;/gi,'&')
    .replace(/&ndash;|&#8211;/gi,'-')
    .replace(/&mdash;|&#8212;/gi,'-')
    .replace(/&minus;|&#8722;/gi,'-')
    .replace(/&percnt;|&#37;/gi,'%')
    .replace(/&deg;/gi,'°')
    .replace(/\s+/g,' ')
    .trim();
}

const MONTHS={
  jan:1,january:1,enero:1,janeiro:1,ocak:1,
  feb:2,february:2,febrero:2,fevereiro:2,subat:2,şubat:2,
  mar:3,march:3,marzo:3,marco:3,março:3,mart:3,
  apr:4,april:4,abril:4,nisan:4,
  may:5,mayo:5,maio:5,mayis:5,mayıs:5,
  jun:6,june:6,junio:6,junho:6,haziran:6,
  jul:7,july:7,julio:7,julho:7,temmuz:7,
  aug:8,august:8,agosto:8,agustos:8,ağustos:8,
  sep:9,september:9,septiembre:9,setembro:9,eylul:9,eylül:9,
  oct:10,october:10,octubre:10,outubro:10,ekim:10,
  nov:11,november:11,noviembre:11,novembro:11,kasim:11,kasım:11,
  dec:12,december:12,diciembre:12,dezembro:12,aralik:12,aralık:12,
};
const MONTH_ABBR=['','Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

function monthNumber(s){ return MONTHS[String(s||'').toLowerCase()] || null; }
function monthPeriod(year, month){ return `${year}-${String(month).padStart(2,'0')}`; }
function quarterFromMonth(month){ return Math.ceil(month/3); }
function rollingPeriod(year,a,b){ return `${year} ${MONTH_ABBR[a]}-${MONTH_ABBR[b]}`; }
function qword(q){ return ({first:1,second:2,third:3,fourth:4,'1st':1,'2nd':2,'3rd':3,'4th':4})[String(q).toLowerCase()] || null; }

function candidate(state,country,metric,value,period,institution,sourceUrl,notes=null,mode='deterministic-direct'){
  const c=findCountry(state,country);
  if(!c) throw new Error(`${country}: missing from state`);
  if(!sourceInstitutionAllowed(country,metric,c.meta?.[metric]?.institution,institution)) throw new Error(`${country}/${metric}: institution mismatch`);
  if(!officialUrlMatches(institution,sourceUrl)) throw new Error(`${country}/${metric}: non-official source URL`);
  const v=num(value); if(v===null) throw new Error(`${country}/${metric}: invalid value`);
  if(!normalizePeriod(period)) throw new Error(`${country}/${metric}: invalid period ${period}`);
  return {country,metric,value:v,period,institution,sourceUrl,status:'OFFICIAL ACTUAL',notes:notes??c.meta[metric].notes,verification:verified(mode)};
}

async function directText(url){
  const raw=await fetchText(url,{
    timeoutMs:35000,
    headers:{accept:'text/html,application/xhtml+xml','cache-control':'no-cache',pragma:'no-cache'}
  });
  const embedded=statsNZPage(raw);
  const parts=embedded ? [embedded.MetaDescription,embedded.FeaturedText,
    ...(embedded.PageBlocks||[]).map(b=>b.Content||'')].filter(Boolean).join(' ') : '';
  return htmlToText(raw+' '+parts);
}

async function browserCall(env, action, args){
  let lastError;
  for(let attempt=1;attempt<=2;attempt++){
    try{
      if(env.__snapshotRun){
        if(env.__snapshotRun.calls>=20) throw new Error('Browser safety budget reached; last verified values retained');
        env.__snapshotRun.calls++;
      }
      const wait=Math.max(0,BROWSER_DELAY_MS-(Date.now()-lastBrowserCall));
      if(wait) await sleep(wait);
      lastBrowserCall=Date.now();
      const res=await env.BROWSER.quickAction(action,args);
      const text=await res.text();
      let doc;
      try{doc=JSON.parse(text);}catch{throw new Error(`Browser ${action} invalid JSON: ${text.slice(0,160)}`);}
      if(doc?.success===false) throw new Error(`Browser ${action} failed: ${JSON.stringify(doc.errors||doc.messages||doc).slice(0,300)}`);
      return doc?.result??doc;
    }catch(e){
      lastError=e;
      const msg=String(e?.message||e);
      const transient=/rate limit|network connection closed|timeout|timed out|2001|5006|6002/i.test(msg);
      if(!transient||attempt===2) throw e;
      await sleep(15000);
    }
  }
  throw lastError;
}

function schemaFor(fields){
  return {type:'json_schema',json_schema:{type:'object',properties:{observations:{type:'array',items:{type:'object',properties:{country:{type:'string'},metric:{type:'string'},value:{type:['number','null']},period:{type:['string','null']},source_url:{type:['string','null']},evidence:{type:['string','null']}},required:['country','metric','value','period','source_url','evidence']}}},required:['observations']}};
}

function confirmationSchema(){
  return {type:'json_schema',json_schema:{type:'object',properties:{observations:{type:'array',items:{type:'object',properties:{country:{type:'string'},metric:{type:'string'},value:{type:['number','null']},period:{type:['string','null']}},required:['country','metric','value','period']}}},required:['observations']}};
}

function buildPrompt(group,state){
  const requests=group.fields.map(f=>{
    const c=findCountry(state,f.country), meta=c?.meta?.[f.metric];
    return `- ${f.country} / ${f.metric}: ${METRICS[f.metric]}. Current accepted observation: ${c?.[f.metric]} for ${meta?.period}.`;
  }).join('\n');
  return 'You are reading an OFFICIAL statistical source for CapitalRisk Global Snapshot.\n'+
    'Extract the newest officially published ACTUAL observation for every requested field below.\n'+requests+
    '\nRules: use only data explicitly published by this official institution; do not use forecasts, outlooks, analyst estimates, quarterly annualised rates, or a different metric. '+
    'GDP must be real GDP growth versus the same quarter one year earlier. Unemployment must be the national headline rate matching the existing series. '+
    'Return period as YYYY-MM for monthly data, YYYY-Q1..Q4 only for genuine calendar-quarter data, or YYYY Mon-Mon for rolling three-month labour data. '+
    'Never convert a rolling labour period such as Apr-Jun or May-Jul into Q2 or Q3. '+
    'source_url must be the exact official page or official PDF containing the value. evidence must include the value and its reference period. '+
    'If the page does not contain a requested observation, return null for value and period. Do not invent anything.';
}

function valueAppears(text,value){
  const v=Number(value);
  const forms=new Set([String(v),...([v.toFixed(1),v.toFixed(2)].filter(x=>Number(x)===v))]);
  return [...forms].some(f=>[f,f.replace('.',',')].some(x=>{
    const escaped=x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    return new RegExp(`(^|[^0-9.,])${escaped}(?![0-9]|[.,][0-9])`).test(text);
  }));
}

function periodAppears(text,period){
  const p=normalizePeriod(period); if(!p) return false;
  const low=text.toLowerCase();
  const y=String(Math.floor(p.key/100));
  if(!low.includes(y)) return false;
  if(p.type==='month'){
    const mo=p.key%100; const eng=['','january','february','march','april','may','june','july','august','september','october','november','december'][mo];
    const aliases=Object.entries(MONTHS).filter(([,n])=>n===mo).map(([s])=>s);
    return low.includes(`${y}-${String(mo).padStart(2,'0')}`)||
      aliases.some(s=>new RegExp(`(^|[^a-z])${s}([^a-z]|$)`,'i').test(low))||
      low.includes(`${y}년 ${mo}월`)||low.includes(`${y}年${mo}月`);
  }
  if(p.type==='quarter'){
    const q=(p.key%100)/3;
    const words=['','first','second','third','fourth'];
    const es=['','primer','segundo','tercer','cuarto'][q];
    const pt=['','primeiro','segundo','terceiro','quarto'][q];
    const roman=['','i','ii','iii','iv'][q];
    return low.includes(`q${q}`)||low.includes(`${q}nd quarter`)||low.includes(`${q}rd quarter`)||low.includes(`${q}th quarter`)||low.includes(`${q}st quarter`)||low.includes(`${words[q]} quarter`)||low.includes(`${q}. ceyrek`)||low.includes(`${q}. çeyrek`)||low.includes(`${es} trimestre`)||low.includes(`${pt} trimestre`)||low.includes(`${roman}. çeyrek`);
  }
  if(p.type==='rolling-quarter'){
    const m=String(period).match(/(\d{4})\s+([A-Za-z]{3})-([A-Za-z]{3})/); if(!m)return false;
    return low.includes(m[2].toLowerCase())&&low.includes(m[3].toLowerCase());
  }
  return true;
}

function metricAppears(text,metric){
  const low=text.toLowerCase();
  if(metric==='unemployment') return /unemployment|desocup|desemprego|işsizlik|issizlik|실업률|tasa de desocupaci/.test(low);
  if(metric==='gdp') return /gross domestic product|\bgdp\b|producto interno bruto|\bpib\b|gayrisafi|국내총생산/.test(low);
  return true;
}

function metricAnchors(text,metric){
  const low=String(text||'').toLowerCase();
  const re=metric==='unemployment'
    ? /unemployment|desocup|desemprego|işsizlik|issizlik|실업률|tasa de desocupaci/g
    : metric==='gdp'
      ? /gross domestic product|\bgdp\b|producto interno bruto|\bpib\b|gayrisafi|국내총생산/g
      : null;
  if(!re) return [0];
  return [...low.matchAll(re)].map(m=>m.index ?? 0);
}

function boundOnOfficialPage(text,metric,value,period){
  const raw=String(text||'');
  for(const idx of metricAnchors(raw,metric)){
    const start=Math.max(0,idx-450), end=Math.min(raw.length,idx+700);
    const window=raw.slice(start,end);
    if(valueAppears(window,value)&&periodAppears(window,period)&&metricAppears(window,metric)) return true;
  }
  return false;
}

async function verifyBrowserCandidate(group,state,raw,url,diag,env){
  const c=findCountry(state,raw.country);
  if(!c) return null;
  const sourceUrl=raw.source_url||url||c.meta?.[raw.metric]?.sourceUrl;
  if(!officialUrlMatches(group.institution,sourceUrl)){
    diag.verificationFailures.push({source:`custom:${group.id}`,country:raw.country,metric:raw.metric,reason:'non-official-source-url'}); return null;
  }
  const value=num(raw.value), period=normalizePeriod(raw.period)?.raw;
  if(value===null||!period||!raw.evidence){
    diag.verificationFailures.push({source:`custom:${group.id}`,country:raw.country,metric:raw.metric,reason:'missing-value-period-or-evidence'}); return null;
  }
  const evidence=String(raw.evidence);

  // Official PDFs/documents are validated by a second independent extraction
  // from the exact same official document. Both runs must agree exactly.
  if(/\.pdf(?:$|[?#])/i.test(sourceUrl)){
    const checkPrompt=`Read ONLY the official ${group.institution} document. For ${raw.country} ${raw.metric}, return the exact published value and reference period. Do not estimate, transform, annualise or round. Return null if uncertain.`;
    const second=await browserCall(env,'json',{
      url:sourceUrl,
      prompt:checkPrompt,
      response_format:confirmationSchema(),
      gotoOptions:{waitUntil:'networkidle2',timeout:45000}
    });
    const obs=(second?.observations||[]).find(o=>String(o.country).toLowerCase()===String(raw.country).toLowerCase()&&String(o.metric).toLowerCase()===String(raw.metric).toLowerCase());
    const v2=num(obs?.value), p2=normalizePeriod(obs?.period)?.raw;
    if(v2!==value||p2!==period){
      diag.verificationFailures.push({source:`custom:${group.id}`,country:raw.country,metric:raw.metric,reason:'double-extraction-mismatch',first:{value,period},second:{value:v2,period:p2}}); return null;
    }
    return {country:raw.country,metric:raw.metric,value,period,institution:group.institution,sourceUrl,status:'OFFICIAL ACTUAL',notes:c.meta[raw.metric].notes,verification:verified('double-browser-official-document',{evidence:evidence.slice(0,220),allowSamePeriodRevision:false})};
  }

  let pageText='', readError=null;
  try{ pageText=await directText(sourceUrl); } catch(e){readError=e;}
  if(!boundOnOfficialPage(pageText,raw.metric,value,period)&&env.BROWSER){
    try{
      const cache=env.__snapshotRun?.pages;
      let rendered=cache?.get(sourceUrl);
      if(!rendered){
        rendered=browserCall(env,'content',{url:sourceUrl,
          rejectResourceTypes:['image','media','font'],
          gotoOptions:{waitUntil:'networkidle2',timeout:25000}});
        cache?.set(sourceUrl,rendered);
      }
      const result=await rendered;
      const html=typeof result==='string'?result:result?.html;
      if(typeof html!=='string')throw new Error('Rendered official page missing HTML');
      pageText=htmlToText(html);
    }catch(e){readError=e;}
  }
  if(!pageText){
    diag.verificationFailures.push({source:`custom:${group.id}`,country:raw.country,metric:raw.metric,reason:`official-page-unreadable:${String(readError?.message||readError||'empty page')}`}); return null;
  }
  const pageHas=boundOnOfficialPage(pageText,raw.metric,value,period);
  const evidenceHas=valueAppears(evidence,value)&&periodAppears(evidence,period)&&metricAppears(evidence,raw.metric);
  if(!pageHas||!evidenceHas){
    diag.verificationFailures.push({
      source:`custom:${group.id}`,
      country:raw.country,
      metric:raw.metric,
      reason:'value-period-metric-not-bound-to-official-page-and-evidence',
      value,period,
      pageHas,evidenceHas
    });
    return null;
  }
  return {country:raw.country,metric:raw.metric,value,period,institution:group.institution,sourceUrl,status:'OFFICIAL ACTUAL',notes:c.meta[raw.metric].notes,verification:verified('official-page-text',{evidence:evidence.slice(0,220)})};
}

function linkObjects(result){
  const raw=Array.isArray(result)?result:Array.isArray(result?.links)?result.links:[];
  return raw.map(x=>typeof x==='string'?{href:x,text:x}:{href:x.href||x.url||x.link,text:x.text||x.title||x.label||x.href||x.url||''}).filter(x=>x.href);
}
function scoreLink(link,keywords){const s=(link.text+' '+link.href).toLowerCase();let score=0;for(const k of keywords||[])if(s.includes(k.toLowerCase()))score+=10;const nums=s.match(/20\d{2}[\/_-]?(0[1-9]|1[0-2])?[\/_-]?(0[1-9]|[12]\d|3[01])?/g)||[];if(nums.length)score+=2;return score;}

/* ---------- deterministic sources ---------- */
const LATVIA_CPI_META='https://api.stat.gov.lv/api/v2/tables/PCI021M/metadata?lang=en';
const LATVIA_CPI_DATA='https://api.stat.gov.lv/api/v2/tables/PCI021M/data';
const LATVIA_CPI_PAGE='https://data.stat.gov.lv/pxweb/en/OSP_PUB/START__VEK__PC__PCI/PCI021m';

function jsonStatCodes(dimension){
  return Object.keys(dimension?.category?.index || {});
}

function jsonStatCodeByLabel(dimension, patterns){
  const labels=dimension?.category?.label || {};
  return Object.keys(labels).find(code=>patterns.some(re=>re.test(String(labels[code]||'')))) || null;
}

async function latviaCPI(state){
  const meta=await fetchJSON(LATVIA_CPI_META,{timeoutMs:35000,headers:{accept:'application/json','cache-control':'no-cache'}});
  const dims=meta?.dimension || {};
  const timeDim=dims.TIME;
  const indicatorDim=dims.ContentsCode;
  const groupDim=dims.ECOICOP_V2;
  if(!timeDim||!indicatorDim||!groupDim) throw new Error('Latvia CSB: PxWeb v2 metadata dimensions not recognized');

  const periods=jsonStatCodes(timeDim).filter(x=>/^20\d{2}M(0[1-9]|1[0-2])$/i.test(x)).sort();
  const latestRaw=periods.at(-1) || null;
  const indicator=jsonStatCodeByLabel(indicatorDim,[/corresponding period of previous year/i,/same period of previous year/i,/year[- ]on[- ]year/i]);
  const total=jsonStatCodeByLabel(groupDim,[/goods and services\s*-?\s*total/i,/all goods and services/i,/total.*goods.*services/i]);
  if(!latestRaw||!indicator||!total) throw new Error('Latvia CSB: latest period, YoY indicator or total CPI code not found');

  const params=new URLSearchParams({
    lang:'en',
    'valueCodes[ECOICOP_V2]':total,
    'valueCodes[ContentsCode]':indicator,
    'valueCodes[TIME]':latestRaw,
    outputFormat:'json-stat2'
  });
  const dataUrl=`${LATVIA_CPI_DATA}?${params.toString()}`;
  const doc=await fetchJSON(dataUrl,{timeoutMs:35000,headers:{accept:'application/json','cache-control':'no-cache'}});
  const rawValues=Array.isArray(doc?.value)?doc.value:Object.values(doc?.value||{});
  const value=rawValues.map(num).find(v=>v!==null);
  const m=String(latestRaw).match(/^(20\d{2})M(0[1-9]|1[0-2])$/i);
  if(value===undefined||!m) throw new Error('Latvia CSB: CPI response missing value or valid monthly period');
  return [candidate(state,'Latvia','inflation',value,`${m[1]}-${m[2]}`,'Central Statistical Bureau of Latvia',dataUrl,'Official national CPI, all goods and services, year on year','official-api')];
}

async function ukONS(state){
  const url='https://www.ons.gov.uk/employmentandlabourmarket/peoplenotinwork/unemployment';
  const t=await directText(url);
  const m=t.match(/Unemployment rate \(aged 16 and over, seasonally adjusted\): %[^0-9]*([0-9]+(?:\.[0-9]+)?)\s*%?\s*(20\d{2})\s*([A-Z]{3})-([A-Z]{3})/i)
    || t.match(/([0-9]+(?:\.[0-9]+)?)\s*%\s*(20\d{2})\s*([A-Z]{3})-([A-Z]{3})/i);
  if(!m) throw new Error('UK ONS: headline unemployment observation not found');
  const a=monthNumber(m[3]),b=monthNumber(m[4]); if(!a||!b)throw new Error('UK ONS: rolling period not understood');
  return [candidate(state,'United Kingdom','unemployment',m[1],rollingPeriod(Number(m[2]),a,b),'Office for National Statistics',url,'Seasonally adjusted LFS estimate')];
}

async function japan(state){
  const latestUrl='https://www.stat.go.jp/english/?s=1&vm=r';
  const latest=await directText(latestUrl);
  const m=latest.match(/Unemployment rate\s*([0-9]+(?:\.[0-9]+)?)\s*%\s*([A-Za-z]+)\s+(20\d{2})\s*seasonally adjusted/i);
  if(!m)throw new Error('Japan: official English unemployment indicator not found');
  const mo=monthNumber(m[2]), period=monthPeriod(Number(m[3]),mo);
  if(!mo)throw new Error('Japan: invalid reference month');
  const out=[candidate(state,'Japan','unemployment',m[1],period,'Statistics Bureau of Japan',latestUrl,'Seasonally adjusted official homepage indicator')];
  const cpi=latest.match(/Consumer Price Index\s*([+-]?[0-9]+(?:\.[0-9]+)?)\s*%\s*([A-Za-z]+)\s+(20\d{2})\s*change over the year/i);
  if(!cpi||!monthNumber(cpi[2]))throw new Error('Japan: national all-items CPI indicator missing');
  out.push(candidate(state,'Japan','inflation',cpi[1],monthPeriod(Number(cpi[3]),monthNumber(cpi[2])),'Statistics Bureau of Japan',latestUrl,'National consumer price index, all items, change over the year'));
  return out;
}

async function australiaGDP(state){
  const url='https://www.abs.gov.au/statistics/economy/national-accounts/australian-national-accounts-national-income-expenditure-and-product/latest-release';
  const t=await directText(url);
  const p=t.match(/Reference period\s+([A-Za-z]+)\s+(20\d{2})/i);
  const v=t.match(/Gross Domestic Product \(GDP\) rose\s*[+-]?[0-9.]+%\s*this quarter and by\s*([+-]?[0-9.]+)%\s*since/i)
    || t.match(/GDP[^.]{0,120}by\s*([+-]?[0-9.]+)%\s*since/i);
  if(!p||!v)throw new Error('Australia GDP: reference period or YoY GDP not found');
  const mo=monthNumber(p[1]); return [candidate(state,'Australia','gdp',v[1],`${p[2]}-Q${quarterFromMonth(mo)}`,'Australian Bureau of Statistics',url,'Through-the-year real GDP growth')];
}

async function australiaJobs(state){
  const url='https://www.abs.gov.au/statistics/labour/employment-and-unemployment/labour-force-australia/latest-release';
  const t=await directText(url);
  const section=t.match(/In seasonally adjusted terms, in ([A-Za-z]+) (20\d{2}):([\s\S]*?)(?:In trend terms|Main features)/i);
  const v=section?.[3].match(/unemployment rate (?:was|(?:increased|decreased|remained)[^.]{0,80}?to)\s*([0-9]+(?:\.[0-9]+)?)\s*%/i)
    || section?.[3].match(/unemployment rate (?:increased|decreased)[\s\S]{0,60}?to\s*([0-9]+(?:\.[0-9]+)?)\s*%/i);
  if(!section||!v||!monthNumber(section[1]))throw new Error('Australia jobs: bound seasonally adjusted observation not found');
  return [candidate(state,'Australia','unemployment',v[1],monthPeriod(Number(section[2]),monthNumber(section[1])),'Australian Bureau of Statistics',url,'Seasonally adjusted')];
}

async function nzJobs(state){
  const url='https://www.stats.govt.nz/indicators/unemployment-rate/';
  const raw=await fetchText(url,{timeoutMs:35000});
  const indicator=statsNZPage(raw)?.FeaturedMedia;
  const ref=indicator?.Period?.match(/^([A-Za-z]+)\s+(20\d{2})\s+quarter$/i);
  if(indicator?.ClassName==='IndicatorBlock'&&/unemployment rate/i.test(indicator.Name||'')&&ref&&monthNumber(ref[1])){
    return [candidate(state,'New Zealand','unemployment',indicator.Value,`${ref[2]}-Q${quarterFromMonth(monthNumber(ref[1]))}`,'Stats NZ',url,'Seasonally adjusted official unemployment rate','official-api')];
  }
  const t=htmlToText(raw);
  const m=t.match(/Unemployment rate\s*([0-9]+(?:\.[0-9]+)?)\s*%\s*([A-Za-z]+)\s+(20\d{2})\s+quarter/i)
    || t.match(/([0-9]+(?:\.[0-9]+)?)\s*percent[^.]{0,80}([A-Za-z]+)\s+(20\d{2})\s+quarter/i);
  if(!m)throw new Error('New Zealand: unemployment observation not found');
  const mo=monthNumber(m[2]); return [candidate(state,'New Zealand','unemployment',m[1],`${m[3]}-Q${quarterFromMonth(mo)}`,'Stats NZ',url,'Seasonally adjusted official unemployment rate')];
}

async function nzCPI(state){
  // Stats NZ CPI is quarterly. Use the canonical information-release URL rather
  // than the generic indicators landing page, whose layout changes frequently.
  const names={3:'march',6:'june',9:'september',12:'december'};
  const now=new Date();
  const y=now.getUTCFullYear(), m=now.getUTCMonth()+1;
  const quarters=[];
  for(let back=0; back<6; back++){
    let yy=y, mm=m-back;
    while(mm<=0){mm+=12;yy--;}
    if([3,6,9,12].includes(mm)) quarters.push([yy,mm]);
  }
  let lastErr=null;
  for(const [yy,mm] of quarters){
    const url=`https://www.stats.govt.nz/information-releases/consumers-price-index-${names[mm]}-${yy}-quarter/`;
    try{
      const t=await directText(url);
      const b=t.match(/consumers price index \(CPI\)[\s\S]{0,120}?quarter and\s*([+-]?[0-9]+(?:\.[0-9]+)?)\s*percent\s+in the 12 months to\s+([A-Za-z]+)\s+(20\d{2})/i)
        || t.match(/consumers price index \(CPI\)[^.%]{0,180}?(?:increased|decreased|rose|fell)[^.%]{0,160}?([+-]?[0-9]+(?:\.[0-9]+)?)\s*percent\s+in the 12 months to(?: the)?\s+([A-Za-z]+)\s+(20\d{2})/i)
        || t.match(/annual inflation at\s*([+-]?[0-9]+(?:\.[0-9]+)?)\s*percent[^.]{0,160}?([A-Za-z]+)\s+(20\d{2})/i);
      let value, py=yy, pm=mm;
      if(b){ value=b[1]; py=Number(b[3]); pm=monthNumber(b[2]); }
      if(value!==undefined && pm){
        return [candidate(state,'New Zealand','inflation',value,monthPeriod(py,pm),'Stats NZ',url,'Official CPI all groups, annual percentage change')];
      }
      lastErr=new Error(`New Zealand: CPI observation not found @ ${url}`);
    }catch(e){ lastErr=e; }
  }
  throw lastErr || new Error('New Zealand: CPI observation not found');
}

