async function southAfricaCPI(state){
  // Stats SA blocks Cloudflare's direct traffic. A GitHub Actions bridge fetches
  // the official Stats SA headline CPI PDF from GitHub-hosted runners and writes
  // only a validated observation to this small JSON cache. The observation keeps
  // Stats SA as the statistical source; GitHub is transport only.
  const bridgeUrl='https://raw.githubusercontent.com/capitalriskdaily-eng/capitalrisk-fred-bridge/main/data/south-africa-cpi.json';
  const doc=await fetchJSON(`${bridgeUrl}?crgs=${Date.now()}`,{timeoutMs:30000,headers:{'cache-control':'no-cache'}});
  if(doc?.schema!=='capitalrisk.south-africa-cpi.bridge.v1') throw new Error('South Africa CPI bridge: invalid schema');
  if(doc?.country!=='South Africa' || doc?.metric!=='inflation') throw new Error('South Africa CPI bridge: wrong field');
  if(doc?.institution!=='Statistics South Africa') throw new Error('South Africa CPI bridge: wrong institution');
  if(!/headline cpi|headline consumer price index/i.test(String(doc?.definition||''))) throw new Error('South Africa CPI bridge: wrong CPI definition');
  if(!/all urban areas/i.test(String(doc?.definition||''))) throw new Error('South Africa CPI bridge: CPI geography not headline all-urban series');
  if(!/^20\d{2}-\d{2}$/.test(String(doc?.period||''))) throw new Error('South Africa CPI bridge: invalid period');
  if(!doc?.sourceUrl || !officialUrlMatches('Statistics South Africa',doc.sourceUrl)) throw new Error('South Africa CPI bridge: source is not official Stats SA');
  return [candidate(
    state,
    'South Africa',
    'inflation',
    doc.value,
    doc.period,
    'Statistics South Africa',
    doc.sourceUrl,
    'Official Stats SA headline CPI for all urban areas; relayed through a GitHub Actions transport bridge because Stats SA blocks Cloudflare traffic',
    'official-bridge'
  )];
}

