async function indiaPLFS(state){
  const archive='https://www.pib.gov.in/allRel.aspx?reg=3&lang=1';
  let page=await fetchText(archive,{timeoutMs:35000});
  const now=new Date();
  for(let back=0;back<3;back++){
    const date=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()-back,1));
    const form=new URLSearchParams();
    for(const tag of page.matchAll(/<input\b[^>]*>/gi)){
      const name=tag[0].match(/\bname="([^"]*)"/i),value=tag[0].match(/\bvalue="([^"]*)"/i);
      if(/\btype="hidden"/i.test(tag[0])&&name)form.set(decodeEntities(name[1]),decodeEntities(value?.[1]||''));
    }
    if(!form.has('__VIEWSTATE')||!form.has('__EVENTVALIDATION'))throw new Error('PIB: archive search form tokens missing');
    for(const [key,value] of Object.entries({
      'ctl00$Bar1$ddlregion':'3','ctl00$Bar1$ddlLang':'1',
      'ctl00$ContentPlaceHolder1$ddlMinistry':'55','ctl00$ContentPlaceHolder1$ddlday':'0',
      'ctl00$ContentPlaceHolder1$ddlMonth':String(date.getUTCMonth()+1),
      'ctl00$ContentPlaceHolder1$ddlYear':String(date.getUTCFullYear()),
      '__EVENTTARGET':'ctl00$ContentPlaceHolder1$ddlMonth','__EVENTARGUMENT':''
    }))form.set(key,value);
    page=await fetchText(archive,{method:'POST',body:form.toString(),timeoutMs:35000,
      headers:{'content-type':'application/x-www-form-urlencoded'}});
    const link=officialLinks(page,archive).find(l=>/Press Note on Periodic Labour Force Survey.*Monthly Bulletin/i.test(l.text));
    if(!link)continue;
    const id=new URL(link.href).searchParams.get('PRID');
    if(!/^\d+$/.test(id||''))throw new Error('PIB: PLFS release identifier missing');
    const url=`https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=${id}&lang=1&reg=3`;
    const t=await directText(url);
    const ref=t.match(/Press Note on Periodic Labour Force Survey\s*\(PLFS\)\s*Monthly Bulletin\s*([A-Za-z]+),?\s*(20\d{2})/i);
    const national=t.match(/Overall UR among persons of age 15 years and above([\s\S]{0,260})/i);
    if(!ref||!national||!monthNumber(ref[1])||!/all-India level[\s\S]{0,80}Current Weekly Status/i.test(t))throw new Error('PIB: national 15+ CWS unemployment definition/reference not found');
    const values=[...national[1].matchAll(/([0-9]+(?:\.[0-9]+)?)\s*%\s*in\s*([A-Za-z]+),?\s*(20\d{2})/gi)];
    const v=values.find(m=>monthNumber(m[2])===monthNumber(ref[1])&&m[3]===ref[2]);
    if(!v)throw new Error('PIB: current national unemployment value not bound to release period');
    return [candidate(state,'India','unemployment',v[1],monthPeriod(Number(ref[2]),monthNumber(ref[1])),
      'Ministry of Statistics and Programme Implementation',url,'PLFS, persons aged 15+, all India, Current Weekly Status; official Ministry press note published by PIB')];
  }
  throw new Error('PIB: monthly PLFS press note not found in the latest three publication months');
}

function ibgeSeries(doc,id,category=null){
  const variable=Array.isArray(doc)?doc.find(v=>String(v.id)===String(id)):null;
  if(!variable||variable.unidade!=='%')throw new Error('IBGE: wrong variable or unit');
  const results=variable.resultados.filter(r=>!category||r.classificacoes?.some(c=>c.categoria?.[category]));
  const series=results.flatMap(r=>r.series||[]).filter(s=>s.localidade?.id==='1'&&s.localidade?.nivel?.id==='N1');
  if(series.length!==1)throw new Error('IBGE: national series is missing or ambiguous');
  const pairs=Object.entries(series[0].serie||{}).filter(([p,v])=>/^20\d{4}$/.test(p)&&num(v)!==null).sort(([a],[b])=>b.localeCompare(a));
  if(!pairs.length)throw new Error('IBGE: no numeric national observation');
  return pairs[0];
}

