function officialLinks(raw,base){
  return [...raw.matchAll(/<a\b([^>]*)>([\s\S]*?)<\/a>/gi)].flatMap(m=>{
    const href=m[1].match(/\bhref=["']([^"']+)["']/i);
    const title=m[1].match(/\btitle=["']([^"']*)["']/i);
    if(!href)return [];
    try{return [{href:new URL(decodeEntities(href[1]),base).toString(),text:htmlToText((title?.[1]||'')+' '+m[2])}];}catch{return [];}
  });
}

async function china(state){
  const base='https://www.stats.gov.cn/english/PressRelease/';
