    gdpLink??=links.find(l=>/Preliminary Accounting Results of GDP/i.test(l.text));
  }
  if(!jobLink||!gdpLink)throw new Error('China NBS: latest national economy or quarterly GDP release not found');
  const [jobsRaw,gdpRaw]=await Promise.all([fetchText(jobLink.href,{timeoutMs:30000}),fetchText(gdpLink.href,{timeoutMs:30000})]);
  const jobs=htmlToText(jobsRaw),gdp=htmlToText(gdpRaw);
  const jm=jobs.match(/In ([A-Za-z]+), the urban surveyed unemployment rate was\s*([0-9]+(?:\.[0-9]+)?)\s*percent/i);
  const released=jobLink.href.match(/\/((?:20\d{2}))(\d{2})\//);
  const gp=gdp.match(/Preliminary Accounting Results of GDP for the (First|Second|Third|Fourth) Quarter[^.]{0,85}?\b(20\d{2})\b/i);
  const table=[...gdpRaw.matchAll(/<table\b[^>]*>([\s\S]*?)<\/table>/gi)].find(m=>/Growth Rate Y\/Y/i.test(htmlToText(m[1])));
  const row=table&&[...table[1].matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi)]
    .map(m=>[...m[1].matchAll(/<t[dh]\b[^>]*>([\s\S]*?)<\/t[dh]>/gi)].map(c=>htmlToText(c[1])))
    .find(c=>c[0]==='GDP');
  if(!jm||!released||!gp||!row||![3,5].includes(row.length)||!monthNumber(jm[1]))throw new Error('China NBS: headline value/reference period not bound to official release');
  const year=Number(released[1])-(monthNumber(jm[1])>Number(released[2])?1:0);
  const yoy=row.length===5?row[3]:row[2];
  return [candidate(state,'China','unemployment',jm[2],monthPeriod(year,monthNumber(jm[1])),'National Bureau of Statistics of China',jobLink.href,'National urban surveyed unemployment rate'),
    candidate(state,'China','gdp',yoy,`${gp[2]}-Q${qword(gp[1])}`,'National Bureau of Statistics of China',gdpLink.href,'Preliminary quarterly real GDP, year on year; not half-year cumulative growth')];
}

