async function browserGroup(group,state,env,diag){
  if(!env.BROWSER)throw new Error('BROWSER binding missing');
  const out=[], failures=[];
  async function extract(url){
    const result=await browserCall(env,'json',{url,prompt:buildPrompt(group,state),response_format:schemaFor(group.fields),gotoOptions:{waitUntil:'networkidle2',timeout:25000}});
    for(const raw of result?.observations||[]){
      if(!group.fields.some(f=>f.country===raw.country&&f.metric===raw.metric))continue;
      if(out.some(c=>c.country===raw.country&&c.metric===raw.metric))continue;
      if(raw.value===null||raw.period===null)continue;
      const local={verificationFailures:[]};
      const v=await verifyBrowserCandidate(group,state,raw,url,local,env);
      failures.push(...local.verificationFailures);
      if(v)out.push(v);
    }
  }
  await extract(group.url);
  // An unverified observation on a landing page is not a successful extraction.
  // Follow the release link in that case too, instead of stopping at potential=true.
  if(out.length<group.fields.length&&group.latestLinkKeywords?.length){
    const links=linkObjects(await browserCall(env,'links',{url:group.url,gotoOptions:{waitUntil:'networkidle2',timeout:25000}}));
    const ranked=links.flatMap(l=>{try{return [{...l,href:new URL(l.href,group.url).toString(),score:scoreLink(l,group.latestLinkKeywords)}];}catch{return [];}})
      .filter(l=>officialUrlMatches(group.institution,l.href)&&l.score>0)
      .sort((a,b)=>b.score-a.score||b.href.localeCompare(a.href));
    if(ranked[0]&&ranked[0].href!==group.url)await extract(ranked[0].href);
  }
  for(const f of failures){
    if(!out.some(c=>c.country===f.country&&c.metric===f.metric))diag.verificationFailures.push(f);
  }
  for(const f of group.fields){
    if(!out.some(c=>c.country===f.country&&c.metric===f.metric)&&
       !failures.some(x=>x.country===f.country&&x.metric===f.metric)){
      diag.verificationFailures.push({source:`custom:${group.id}`,country:f.country,metric:f.metric,reason:'official-observation-not-found'});
    }
  }
  return out;
}

export async function getCustomCandidates(state,env,diag,onlyIds=null){
  env={...env,__snapshotRun:{calls:0,pages:new Map()}};
  const all=[];
  const selected=Array.isArray(onlyIds)&&onlyIds.length?CUSTOM_SOURCE_GROUPS.filter(g=>onlyIds.includes(g.id)):CUSTOM_SOURCE_GROUPS;
  const executedShared=new Set();
  const confirmed=new Set(diag.confirmedFields||[]);

  for(const group of selected){
    try{
      const fn=DIRECT[group.id];
      let cands;
      if(fn){
        // Colombia GDP/jobs share one deterministic fetch function. Avoid duplicate work in a full run.
        const shared=fn===colombia?'colombia':group.id;
        if(executedShared.has(shared)){
          diag.sources.push({source:`custom:${group.id}`,ok:true,candidates:0,mode:'deterministic-direct-shared'});
          continue;
        }
        executedShared.add(shared);
        try{
          cands=await fn(state,env,diag);
        }catch(directError){
          if(!env.BROWSER||['south-africa-cpi','south-africa-jobs'].includes(group.id))throw directError;
          if(group.fields.every(f=>confirmed.has(`${f.country}/${f.metric}`))){
            diag.recoveredSources??=[];
            diag.recoveredSources.push({source:`custom:${group.id}`,directError:String(directError.message),mode:'confirmed-standard-official-source'});
            diag.sources.push({source:`custom:${group.id}`,ok:true,candidates:0,mode:'confirmed-standard-official-source'});
            continue;
          }
          cands=await browserGroup(group,state,env,diag);
          if(!cands.length)throw new Error(`Direct parser: ${directError.message}; browser fallback found no independently verified observation`);
          diag.recoveredSources??=[];
          diag.recoveredSources.push({source:`custom:${group.id}`,directError:String(directError.message),mode:'browser-with-official-page-verification'});
        }
        cands=cands.filter(c=>group.fields.some(f=>f.country===c.country&&f.metric===c.metric) || shared==='colombia');
        // When running only one Colombia group, return only the requested metric.
        if(onlyIds?.length) cands=cands.filter(c=>group.fields.some(f=>f.country===c.country&&f.metric===c.metric));
        all.push(...cands);
        diag.sources.push({source:`custom:${group.id}`,ok:true,candidates:cands.length,mode:'deterministic-direct'});
      }else{
        if(group.fields.every(f=>confirmed.has(`${f.country}/${f.metric}`))){
          diag.sources.push({source:`custom:${group.id}`,ok:true,candidates:0,mode:'confirmed-standard-official-source'});
          continue;
        }
        cands=await browserGroup(group,state,env,diag);
        all.push(...cands);
        diag.sources.push({source:`custom:${group.id}`,ok:true,candidates:cands.length,mode:'browser+official-page-verification'});
      }
    }catch(e){
      diag.sourceErrors.push({source:`custom:${group.id}`,error:String(e?.message||e)});
    }
  }
  diag.browserCalls=env.__snapshotRun.calls;
  return all;
}

