// the euro-area aggregate, consistent with the CapitalRisk maintenance policy.
const EUROSTAT_INFLATION_COUNTRIES = new Set([
  "Euro Area","Germany","France","Italy","Spain","Netherlands","Belgium",
  "Austria","Portugal","Finland","Greece","Ireland","Slovakia","Slovenia",
  "Luxembourg","Estonia","Latvia","Lithuania","Croatia","Cyprus","Malta",
  "Bulgaria","Poland","Czechia","Sweden","Denmark"
]);

export function sourceInstitutionAllowed(countryName, metric, currentInstitution, candidateInstitution) {
  const explicit = SOURCE_POLICIES?.[countryName]?.[metric];
  if (explicit?.blocked) return false;
  if (!candidateInstitution) return false;
  if (candidateInstitution === currentInstitution) return true;
  if (explicit?.allowed?.includes(candidateInstitution)) return true;

  if (candidateInstitution === "Eurostat" && metric === "inflation") {
    return EUROSTAT_INFLATION_COUNTRIES.has(countryName);
  }

  if (STANDARD_ALLOWED?.[metric]?.includes(candidateInstitution)) return true;

  // National sources are only emitted by explicitly configured deterministic/
  // verified custom adapters, so they are safe to accept as primary sources.
  if (NATIONAL_OFFICIAL.has(candidateInstitution)) return true;

  return false;
}

export function sourcePriority(countryName, metric, institution) {
  const explicit = SOURCE_POLICIES?.[countryName]?.[metric];
  if (explicit?.primary === institution) return 500;

  if (NATIONAL_OFFICIAL.has(institution)) return 400;

  const ranks = {
    rate: {
      "Bank for International Settlements": 100,
    },
    inflation: {
      "Eurostat": 300,
      "OECD": 200,
      "Bank for International Settlements": 100,
    },
    gdp: {
      "Eurostat": 300,
      "OECD": 200,
      "IMF World Economic Outlook": 100,
    },
    unemployment: {
      "Eurostat": 300,
      "OECD": 200,
      "IMF World Economic Outlook": 100,
    },
    debt: {
      "IMF World Economic Outlook": 100,
    },
  };
  return ranks?.[metric]?.[institution] ?? 0;
}

