// too aggressive. The daily source check still runs normally.
const FIELD_LIMIT_MONTHS = Object.freeze({
  'New Zealand': Object.freeze({ inflation: 4, unemployment: 6 }), // quarterly releases
  'South Africa': Object.freeze({ unemployment: 6 }), // quarterly QLFS
  'Saudi Arabia': Object.freeze({ unemployment: 6 }), // quarterly labour release with publication lag
  'Argentina': Object.freeze({ unemployment: 6 }), // quarterly EPH release with publication lag
});

function limitMonths(countryName, metric, meta) {
  // Switzerland's harmonised ILO labour-force observation is quarterly. Keep
  // the ordinary monthly threshold for a genuinely monthly registered series.
  if(countryName==='Switzerland' && metric==='unemployment' &&
    ['Eurostat','OECD'].includes(meta?.institution) &&
    /(?:-Q[1-4]|-(?:03|06|09|12))$/.test(meta?.period||'')) return 6;
  return FIELD_LIMIT_MONTHS?.[countryName]?.[metric] ?? LIMIT_MONTHS[metric] ?? 6;
}

export function currentMonthKey(now = new Date()) {
  return now.getUTCFullYear() * 100 + (now.getUTCMonth() + 1);
}

export function monthsBetweenKeys(nowKey, periodKey) {
  const ny = Math.floor(nowKey / 100), nm = nowKey % 100;
  const py = Math.floor(periodKey / 100), pm = periodKey % 100;
  return (ny - py) * 12 + (nm - pm);
}


export function periodLagMonths(period, now = new Date()) {
  const p = typeof period === 'string' ? normalizePeriod(period) : period;
  if (!p || p.type === 'weo' || p.type === 'year') return null;
  return monthsBetweenKeys(currentMonthKey(now), p.key);
}

export function periodFreshEnough(metric, period, now = new Date()) {
  const lag = periodLagMonths(period, now);
  if (lag === null) return true;
  return lag <= (LIMIT_MONTHS[metric] ?? 6);
}

export function auditFreshness(state, now = new Date()) {
  const out = [];
  const nowKey = currentMonthKey(now);
  const metrics = ['rate','inflation','gdp','unemployment','debt'];

  for (const country of state?.countries || []) {
    for (const metric of metrics) {
      const value = country?.[metric];
      const meta = country?.meta?.[metric];
      if (country?.name === 'Argentina' && metric === 'rate' && value === null) continue;
      const p = normalizePeriod(meta?.period);
      if (!p) {
        out.push({country:country?.name || null, metric, period:meta?.period || null, institution:meta?.institution || null, reason:'unparseable-period'});
        continue;
      }
      if (p.type === 'weo' || p.type === 'year') continue;
      const lagMonths = monthsBetweenKeys(nowKey, p.key);
      const limit = limitMonths(country.name, metric, meta);
      if (lagMonths > limit) {
        out.push({
          country:country.name,
          metric,
          period:p.raw,
          institution:meta?.institution || null,
          lagMonths,
          warningAfterMonths:limit,
          reason:'reference-period-lag'
        });
      }
    }
  }
  return out;
}

import { SEED_DATA } from "./seed.js";
import { jsonResponse, nowISO } from "./utils.js";
import { DIAG_KEY, STATE_KEY, loadState, refreshSnapshot } from "./refresh.js";
import { getCustomCandidates } from "./adapters/custom.js";
import { applyAuditedCorrections } from "./corrections.js";
import { auditFreshness } from "./freshness.js";

const REPAIR_VERSION='2026-10-06-source-repair-2';

function authorized(request,env){
  const token=request.headers.get("authorization")?.replace(/^Bearer\s+/i,"") || new URL(request.url).searchParams.get("token");
  return Boolean(env.ADMIN_TOKEN && token && token===env.ADMIN_TOKEN);
}

export default {
  async fetch(request,env){
    const url=new URL(request.url);
    if(request.method==="OPTIONS") return new Response(null,{headers:{"access-control-allow-origin":"*","access-control-allow-methods":"GET,POST,OPTIONS","access-control-allow-headers":"authorization,content-type"}});
    if(url.pathname==="/" || url.pathname==="/global-snapshot"){
      const state=await loadState(env);
      const diag=await env.SNAPSHOT_KV.get(DIAG_KEY,{type:"json"});
      const stale=auditFreshness(state);
      return jsonResponse({
        status:"ok",dataset:state.dataset,version:state.version,
        lastCheckedAt:state.lastCheckedAt||state.lastRunAt||null,
        lastChangeAt:state.lastChangeAt||null,
        lastSuccessfulRun:state.lastSuccessfulRun||null,
        runStatus:state.lastRunStatus||null,
        sourceErrorsCount:diag?.sourceErrors?.length||0,
        verificationFailuresCount:diag?.verificationFailures?.length||0,
        staleFieldsCount:stale.length,
        countries:state.countries
      });
    }
    if(url.pathname==="/health"){
      const state=await loadState(env); const diag=await env.SNAPSHOT_KV.get(DIAG_KEY,{type:"json"});
      const stale=auditFreshness(state);
      const age=Date.now()-Date.parse(state.lastCheckedAt||'');
      const dataHealthy=!stale.length && Number.isFinite(age) && age>=0 && age<36*60*60*1000;
      const sourceWarnings=(diag?.sourceErrors?.length||0)+(diag?.verificationFailures?.length||0);
      return jsonResponse({
        status:!dataHealthy?'partial':(sourceWarnings?'ok-with-warnings':'ok'),repairVersion:REPAIR_VERSION,
        healthy:dataHealthy && !sourceWarnings,
        dataHealthy,
        sourceWarningsCount:sourceWarnings,
        now:nowISO(),countries:state.countries.length,fields:state.countries.length*5,
        lastCheckedAt:state.lastCheckedAt||state.lastRunAt||null,
        lastChangeAt:state.lastChangeAt||null,
        lastSuccessfulRun:state.lastSuccessfulRun||null,
        runStatus:state.lastRunStatus||null,
        staleFieldsCount:stale.length,
        staleFields:stale.slice(0,25),
        lastRun:diag?{started:diag.started,finished:diag.finished,updated:diag.updated?.length||0,revisions:diag.revisions?.length||0,sourceUpgrades:diag.sourceUpgrades?.length||0,auditedCorrections:diag.auditedCorrections?.length||0,sourceErrors:diag.sourceErrors||[],verificationFailures:diag.verificationFailures||[]}:null
      });
    }
    if(url.pathname==="/diagnostics"){
      if(!authorized(request,env)) return jsonResponse({error:"unauthorized"},401);
      return jsonResponse(await env.SNAPSHOT_KV.get(DIAG_KEY,{type:"json"}) || {status:"never-run"});
    }
    if(url.pathname==="/admin/test-custom"){
      if(!authorized(request,env))
        return jsonResponse({error:"unauthorized"},401);

      const only=(url.searchParams.get("only")||"")
        .split(",")
        .map(x=>x.trim())
        .filter(Boolean);

      const state=await loadState(env);
      const diag={sources:[],sourceErrors:[],verificationFailures:[],updated:[],revisions:[],unchanged:[],rejected:[]};

      const candidates=await getCustomCandidates(
        state,
        env,
        diag,
        only
      );

      return jsonResponse({
        status:"test-only",
        tested:only,
        candidates,
        sourceErrors:diag.sourceErrors,
        verificationFailures:diag.verificationFailures,
        sources:diag.sources
      });
    }

    if(url.pathname==="/admin/apply-audited-corrections"){
      if(!authorized(request,env)) return jsonResponse({error:"unauthorized"},401);
      const state=await loadState(env);
      const result=applyAuditedCorrections(state);
      state.lastRunAt=nowISO();
      await env.SNAPSHOT_KV.put(STATE_KEY,JSON.stringify(state));
      return jsonResponse({status:"done",...result});
    }

    if(url.pathname==="/admin/refresh-export"){
      if(!authorized(request,env)) return jsonResponse({error:"unauthorized"},401);
      const includeCustom=url.searchParams.get("custom")!=="0";
      const {state,diag}=await refreshSnapshot(env,{includeCustom});
      return jsonResponse({
        status:"done",
        snapshot:{
          status:"ok",
          dataset:state.dataset,
          version:state.version,
          lastCheckedAt:state.lastCheckedAt||state.lastRunAt||null,
          lastChangeAt:state.lastChangeAt||null,
          lastSuccessfulRun:state.lastSuccessfulRun||null,
          runStatus:state.lastRunStatus||null,
          staleFieldsCount:diag.staleWarnings?.length||0,
          sourceErrorsCount:diag.sourceErrors?.length||0,
          verificationFailuresCount:diag.verificationFailures?.length||0,
          countries:state.countries
        },
        diagnostics:diag
      });
    }

    if(url.pathname==="/admin/refresh"){
      if(!authorized(request,env)) return jsonResponse({error:"unauthorized"},401);
      const includeCustom=url.searchParams.get("custom")!=="0";
      const {diag}=await refreshSnapshot(env,{includeCustom});
      return jsonResponse({status:"done",runStatus:diag.runStatus,updated:diag.updated,revisions:diag.revisions,sourceUpgrades:diag.sourceUpgrades,auditedCorrections:diag.auditedCorrections,rejected:diag.rejected,verificationFailures:diag.verificationFailures,sourceErrors:diag.sourceErrors,staleWarnings:diag.staleWarnings,sources:diag.sources,finished:diag.finished});
    }
    if(url.pathname==="/admin/reset"){
      if(!authorized(request,env)) return jsonResponse({error:"unauthorized"},401);
      const state={version:1,dataset:"CapitalRisk Global Snapshot",countries:JSON.parse(JSON.stringify(SEED_DATA)),initializedAt:nowISO(),lastCheckedAt:null,lastChangeAt:null,lastSuccessfulRun:null,lastRunStatus:null};
      await env.SNAPSHOT_KV.put(STATE_KEY,JSON.stringify(state));
      await env.SNAPSHOT_KV.delete(DIAG_KEY);
      return jsonResponse({status:"reset",countries:state.countries.length});
    }
    return jsonResponse({error:"not-found"},404);
  },
  async scheduled(_event,env,ctx){
    ctx.waitUntil(refreshSnapshot(env,{includeCustom:true}));
  }
};

import { normalizePeriod, parseNumber } from './utils.js';
import { sourceInstitutionAllowed } from './config.js';

const OFFICIAL_ROOTS = {
  'Reserve Bank of India': ['rbi.org.in'],
  'Office for National Statistics': ['ons.gov.uk'],
  'Statistics Bureau of Japan': ['stat.go.jp'],
  'National Bureau of Statistics of China': ['stats.gov.cn'],
  'Australian Bureau of Statistics': ['abs.gov.au'],
  'Stats NZ': ['stats.govt.nz'],
  'IBGE': ['ibge.gov.br'],
  'Ministry of Statistics and Programme Implementation': ['mospi.gov.in','pib.gov.in'],
  'Bank of Korea': ['bok.or.kr'],
  'Ministry of Data and Statistics (KOSTAT)': ['kostat.go.kr'],
  'INEGI': ['inegi.org.mx'],
  'Statistics South Africa': ['statssa.gov.za'],
  'Turkish Statistical Institute': ['tuik.gov.tr'],
  'General Authority for Statistics': ['stats.gov.sa'],
  'Central Bank of Argentina': ['bcra.gob.ar'],
  'INDEC': ['indec.gob.ar'],
  'National Statistics Institute of Chile': ['ine.gob.cl'],
  'DANE': ['dane.gov.co'],
  'Central Statistical Bureau of Latvia': ['stat.gov.lv'],
  'Bank for International Settlements': ['bis.org'],
  'Eurostat': ['europa.eu'],
  'IMF World Economic Outlook': ['imf.org'],
  'OECD': ['oecd.org'],
};

function host(url) {
  try { return new URL(url).hostname.toLowerCase().replace(/^www\./, ''); }
  catch { return null; }
}

export function officialUrlMatches(institution, url) {
  try { if(new URL(url).protocol!=='https:') return false; } catch { return false; }
  const h = host(url);
  if (!h) return false;
  const roots = OFFICIAL_ROOTS[institution] || [];
  return roots.some(root => h === root || h.endsWith(`.${root}`));
}

function periodTypeCompatible(current, candidate, {metric, currentStatus, candidateStatus} = {}) {
  if (!current || !candidate) return false;
  if (current.type === candidate.type) return true;

  // A WEO annual estimate is a fallback placeholder. A verified official ACTUAL
  // quarterly/monthly observation for GDP or unemployment is allowed to replace
  // that estimate; otherwise the robot can never graduate from forecast to actual.
  const estimateToActual =
    current.type === 'weo' &&
    /ESTIMATE/i.test(currentStatus || '') &&
    /ACTUAL/i.test(candidateStatus || '') &&
    ['gdp','unemployment'].includes(metric) &&
    ['quarter','month','rolling-quarter'].includes(candidate.type);
  if (estimateToActual) return true;

  // Monthly and rolling labour series must never be silently converted into quarters.
  return false;
}

function periodNotInFuture(p, status) {
  if (!p) return false;
  if (/ESTIMATE/i.test(status || '') || p.type === 'weo') return true;
  const now = new Date();
  const monthKey = now.getUTCFullYear() * 100 + (now.getUTCMonth() + 1);
  return p.key <= monthKey;
}

export function validateCandidateForState(country, metric, candidate) {
  const problems = [];
  const oldMeta = country?.meta?.[metric];
  const verification = candidate?.verification;
  const value = parseNumber(candidate?.value);
  const currentPeriod = normalizePeriod(oldMeta?.period);
  const candidatePeriod = normalizePeriod(candidate?.period);

  if (/NOT APPLICABLE/i.test(oldMeta?.status || '') && !verification?.overrideNotApplicable) problems.push('field-not-applicable');
  if (!verification?.verified) problems.push('not-verified');
  if (!candidate?.institution || !sourceInstitutionAllowed(country?.name, metric, oldMeta?.institution, candidate.institution)) problems.push('institution-mismatch');
  if (!candidate?.sourceUrl || !officialUrlMatches(candidate.institution, candidate.sourceUrl)) problems.push('non-official-source-url');
  if (!candidatePeriod) problems.push('invalid-period');
  if (currentPeriod && candidatePeriod && !periodTypeCompatible(currentPeriod, candidatePeriod, {
    metric,
    currentStatus: oldMeta?.status,
    candidateStatus: candidate?.status,
  }) && !(country?.name==='Brazil' && metric==='unemployment' &&
    currentPeriod.type==='quarter' && candidatePeriod.type==='rolling-quarter' &&
    candidate.institution==='IBGE' && /ACTUAL/i.test(candidate.status||'') &&
    verification?.verified)) problems.push('period-type-mismatch');
  if (candidatePeriod && !periodNotInFuture(candidatePeriod, candidate.status || oldMeta?.status)) problems.push('future-period');
  if (value === null) problems.push('invalid-value');

  return { ok: problems.length === 0, problems, currentPeriod, candidatePeriod };
}

export function verified(mode, extra = {}) {
  return {
    verified: true,
    mode,
    checkedAt: new Date().toISOString(),
    allowSamePeriodRevision: mode === 'official-api' || mode === 'deterministic-direct' || mode === 'official-page-text' || mode === 'official-bridge',
    ...extra,
  };
}
